-- Homepage
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"SEO for local, regional, and industrial businesses","heading":"Search Visibility, Explained Every Month.","body":"Jordan Marketing Consultants does one thing: search visibility for local, regional, and industrial businesses. Every month you get a plain recap of what was done, why, and what changed.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"See How JMC Reports SEO Progress","href":"#monthly-recap"},"showcase":[{"kind":"report","label":"Every month","title":"Monthly Recap","items":["What was done","Why it matters","What changed","What comes next"]},{"kind":"coverage","label":"Where you appear","title":"Search Visibility","items":["Search","Maps","Local grid"]},{"kind":"roadmap","label":"The plan","title":"SEO Roadmap","items":["Priorities set","Content queued","Technical fixes tracked"]}]}'::jsonb, 0 from public.pages where slug = '/';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'growth-paths', 'cardGrid', 'surface', '{"eyebrow":"SEO Growth Paths","heading":"Choose the SEO Path That Fits Where You Are Growing","body":"Different businesses need different SEO strategies. JMC helps visitors find the right path based on market size, competition, audience, and growth goals.","columns":3,"cards":[{"title":"Local SEO","icon":"map-pin","body":"For businesses that need stronger visibility in Google Search, Google Maps, and local service-area searches.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"trending-up","body":"For regional, national, and industry-focused companies competing across larger search markets.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}},{"title":"Real Estate SEO","icon":"home","body":"For agents, teams, and brokerages that want stronger local search presence and content that supports trust.","cta":{"label":"Explore Real Estate SEO","href":"/real-estate-seo"}}]}'::jsonb, 1 from public.pages where slug = '/';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'transparency', 'fullWidthText', NULL, '{"treatment":"statement","heading":"No Mystery SEO. No Confusing Reports. No Guessing What You Paid For.","body":"Most agencies keep the work behind a login and the reasoning to themselves. JMC does the opposite. You see what was done, why it was done, and what it changed, in language that does not need translating. That is how the work is run, not a reporting add-on.","cta":{"label":"See How JMC Reports SEO Progress","href":"#monthly-recap"}}'::jsonb, 2 from public.pages where slug = '/';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'services', 'cardGrid', 'white', '{"eyebrow":"SEO Services","heading":"SEO Work Built Around Strategy, Visibility, and Accountability","body":"JMC focuses on the pieces of SEO that help businesses become easier to find, easier to understand, and easier to trust in search.","columns":3,"cards":[{"title":"SEO Strategy","icon":"target","body":"Keyword priorities, search intent, competitor visibility, and roadmap planning."},{"title":"Local Optimization","icon":"map-pin","body":"Local search improvements that support visibility in Google Search, Google Maps, and service-area searches."},{"title":"Google Business Profile Support","icon":"star","body":"Profile optimization, post strategy, service alignment, and activity that supports local trust."},{"title":"SEO Content Planning","icon":"file-text","body":"Strategic SEO pages, content roadmaps, service page improvements, and search-focused messaging."},{"title":"Technical SEO Monitoring","icon":"wrench","body":"Ongoing review of technical issues that can affect crawling, indexing, visibility, and site performance."},{"title":"Reporting and Monthly Recaps","icon":"bar-chart","body":"Clear monthly updates that explain progress, priorities, and next steps without burying you in jargon."}],"cta":{"label":"Explore SEO Services","href":"/local-seo-services"}}'::jsonb, 3 from public.pages where slug = '/';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'industries', 'industryGrid', 'surface', '{"eyebrow":"Industries","heading":"Where This Method Gets Pointed","body":"One method, aimed at two different kinds of search problem.","groups":[{"label":"Businesses that serve a defined area","serviceLine":"Local SEO","serviceHref":"/local-seo-services","cards":[{"title":"Home Services & Trades","icon":"wrench","body":"Roofers, plumbers, electricians, and the trades that live on calls from a service area.","href":"/local-seo-services"},{"title":"Healthcare & Wellness","icon":"heart-pulse","body":"Practices and clinics where people check credibility before they ever call.","href":"/local-seo-services"},{"title":"Hospitality & Attractions","icon":"utensils","body":"Venues, parks, and places people search for by what they want to do, not by name.","href":"/local-seo-services"},{"title":"Professional Services","icon":"briefcase","body":"Firms whose next client is comparing three local options in a single sitting.","href":"/local-seo-services"}]},{"label":"Businesses selling across multiple markets","serviceLine":"Traditional SEO","serviceHref":"/traditional-seo-services","cards":[{"title":"Energy & Petrochemical","icon":"factory","body":"Operators and suppliers selling technical capability to a small, specific buyer pool.","href":"/traditional-seo-services"},{"title":"Maritime & Logistics","icon":"network","body":"Port, freight, and supply chain businesses working across regions rather than a radius.","href":"/traditional-seo-services"},{"title":"Commercial Construction","icon":"hard-hat","body":"Contractors and infrastructure firms bidding well outside one city.","href":"/traditional-seo-services"},{"title":"Aerospace & Aviation","icon":"compass","body":"Suppliers and services in a market where the search volume is low and the intent is high.","href":"/traditional-seo-services"}]}],"escapeHatch":"The method does not change with the industry. If yours is not listed, it probably still applies."}'::jsonb, 4 from public.pages where slug = '/';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'packages', 'cardGrid', 'white', '{"eyebrow":"SEO Packages","heading":"SEO Options Built for Different Growth Stages","body":"JMC offers structured SEO options for businesses that need ongoing monthly support or a focused starting point before moving into a longer campaign.","columns":3,"cards":[{"title":"Monthly Local SEO","icon":"map-pin","meta":"From $875/mo","body":"For businesses that need consistent local visibility support across search, maps, content, reviews, and reporting.","cta":{"label":"View Local SEO Packages","href":"/seo-packages#local"}},{"title":"Monthly Traditional SEO","icon":"trending-up","meta":"From $2,295/mo","body":"For businesses targeting regional, national, or competitive industry visibility with a larger search footprint.","cta":{"label":"View Traditional SEO Packages","href":"/seo-packages#traditional"}},{"title":"Launch Sprints","icon":"compass","meta":"From $799 one-time","body":"For businesses that need a fixed-scope SEO foundation before deciding on monthly service.","cta":{"label":"View Launch Sprints","href":"/launch-sprints"}}]}'::jsonb, 5 from public.pages where slug = '/';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'process', 'processSteps', 'surface', '{"eyebrow":"How It Works","heading":"A Clear SEO Process From Review to Recap","body":"SEO works better when the process is organized. JMC keeps the work focused around visibility, priorities, implementation, and clear communication.","steps":[{"title":"Visibility Review","body":"We review where your business currently shows up, where visibility is weak, and which opportunities are worth prioritizing."},{"title":"SEO Roadmap","body":"We organize the work around keyword priorities, content needs, local visibility, technical issues, and business goals."},{"title":"Implementation","body":"We complete the scoped SEO work, content updates, local optimization, and technical improvements tied to the plan."},{"title":"Monthly Recap","body":"You receive a clear summary of what was completed, what changed, and what should happen next."}],"cta":{"label":"Start with a Visibility Review","href":"/contact"}}'::jsonb, 6 from public.pages where slug = '/';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Clear Reporting","heading":"What You Get Every Month","body":"SEO should not feel vague. Every month you get the same four answers, in the same order, in language that does not need a glossary.","did":"A plain summary of the SEO work completed: content, technical checks, local visibility tasks, and everything else inside the scope.","why":"The reasoning behind each piece of work, and how it supports visibility, relevance, or trust.","changed":"What moved, what did not, and what we are still watching.","next":"The priorities for the coming month, in order, so you always know where the campaign is heading.","cta":{"label":"See How JMC Reports SEO Progress","href":"#monthly-recap"}}'::jsonb, 7 from public.pages where slug = '/';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'houston', 'fullWidthText', 'surface', '{"eyebrow":"Houston-Area SEO Agency","heading":"Rooted in League City. Built for Houston-Area Growth.","body":"JMC is based in League City and works with businesses across the Houston area that need practical SEO strategy, stronger search visibility, and clearer reporting. Whether the goal is local visibility, regional growth, or a more focused real estate SEO strategy, the work starts with understanding where your business is trying to grow.","cta":{"label":"Learn More About JMC","href":"/about"}}'::jsonb, 8 from public.pages where slug = '/';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Not Sure Where Your SEO Is Stuck? Start with a Visibility Review.","body":"We will help you identify visibility gaps, priority opportunities, and the best next step based on your business, market, and goals.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View SEO Packages","href":"/seo-packages"}}'::jsonb, 9 from public.pages where slug = '/';

-- Local SEO Services
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Local SEO Services","heading":"Get Found by the People Searching in Your Service Area","body":"Local SEO helps your business show up when nearby customers search for what you do. JMC works on the pieces that drive local visibility: your Google Business Profile, your service pages, your local listings, your reviews, and the reporting that shows what changed.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Local SEO Packages","href":"/seo-packages#local"},"showcase":[{"kind":"stat","label":"Neighborhood tier","title":"What Gets Tracked","stats":[{"value":"30","label":"Tracked keywords"},{"value":"3","label":"Tracked competitors"},{"value":"8","label":"Profile posts a month"}],"footnote":"Scales with Citywide and Metro"},{"kind":"coverage","label":"Service area","title":"Local Search Grid","items":["Neighborhood","Citywide","Metro"]},{"kind":"channels","label":"Where you appear","title":"Local Surfaces","items":["Google Search results","Google Maps and the map pack","Service-area searches"],"footnote":"Tracked across your whole service area"}]}'::jsonb, 0 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'audience-fit', 'cardGrid', 'white', '{"variant":"split","eyebrow":"Is This You","heading":"Local SEO Is the Right Path When Your Customers Are Nearby","body":"If your business depends on people finding you in a specific city or service area, local SEO is where the work should start.","columns":3,"cards":[{"title":"A Defined Local Market","icon":"map-pin","body":"You serve a city, a set of neighborhoods, or a drive-time radius rather than a national audience."},{"title":"Search and Maps Visibility","icon":"search","body":"You need to appear in both regular Google results and the map pack when someone searches nearby."},{"title":"Service Pages That Work","icon":"file-text","body":"Your services need pages that explain what you do clearly enough for search engines and buyers to understand."},{"title":"Google Business Profile Support","icon":"star","body":"Your profile needs consistent attention, not a one-time setup that goes stale after a month."},{"title":"Reporting You Can Read","icon":"bar-chart","body":"You want to know what was done and what changed without decoding a dashboard on your own."}],"cta":{"label":"See What Local SEO Includes","href":"#includes"}}'::jsonb, 1 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'includes', 'cardGrid', 'surface', '{"variant":"numbered","eyebrow":"What''s Included","heading":"The Work Behind Local Search Visibility","body":"Local SEO is a set of connected workstreams. These are the pieces JMC manages month to month.","columns":3,"cards":[{"title":"Google Business Profile Optimization","icon":"star","body":"Profile completeness, categories, services, posts, photos, and the ongoing activity that supports local trust."},{"title":"Local Content and Service Pages","icon":"file-text","body":"Strategic SEO pages and service page improvements built around what local buyers actually search for."},{"title":"Citation and Listing Support","icon":"link","body":"Consistent name, address, and phone details across the directories and platforms that influence local results."},{"title":"Review Support","icon":"message-square","body":"Review request sends and reply management so your reputation keeps building instead of stalling."},{"title":"Local Rank Tracking","icon":"gauge","body":"Local search grid tracking that shows where you appear across your service area, not just one average position."},{"title":"Monthly Recaps and Reporting","icon":"clipboard-check","body":"A plain-English summary of what was completed, what moved, and what is prioritized next."}],"cta":{"label":"Compare Local SEO Packages","href":"/seo-packages#local"}}'::jsonb, 2 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'system', 'featureSplit', 'white', '{"eyebrow":"How It Fits Together","heading":"Local Visibility Is One System, Not Six Separate Tasks","body":"Each piece of local SEO supports the others. A strong Google Business Profile works better when your service pages back it up. Reviews matter more when your listings are consistent. Tracking only helps if someone reads it and acts on it. JMC manages these as one system and reports on them together.","cta":{"label":"Start with a Visibility Review","href":"/contact"},"groups":[{"title":"Google Business Profile","icon":"star","body":"The front door for local search and map results."},{"title":"Website Content","icon":"file-text","body":"Service and location pages that explain what you do."},{"title":"Citations and Listings","icon":"link","body":"Consistent business details across the platforms that count."},{"title":"Reviews","icon":"message-square","body":"Ongoing requests and replies that build local trust."},{"title":"Tracking","icon":"gauge","body":"Grid-based visibility tracking across your service area."},{"title":"Monthly Recaps","icon":"clipboard-check","body":"The summary that ties the month''s work back to priorities."}]}'::jsonb, 3 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'houston', 'fullWidthText', 'surface', '{"eyebrow":"Houston-Area SEO Agency","heading":"Rooted in League City. Built for Houston-Area Growth.","body":"JMC is based in League City and works with businesses across the Greater Houston area. Local SEO is not limited to one part of the map. The strategy is built around where your customers actually are and where your business is trying to grow.","cta":{"label":"Learn More About JMC","href":"/about"}}'::jsonb, 4 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'packages', 'pricingCards', 'white', '{"eyebrow":"Local SEO Packages","heading":"Monthly Local SEO Built Around Your Market Size","body":"Three levels of ongoing local SEO support. Every package includes strategy, on-page work, technical monitoring, review management, and a Monthly Recap.","packageIds":["local-neighborhood","local-citywide","local-metro"],"cta":{"label":"View All SEO Packages","href":"/seo-packages"}}'::jsonb, 5 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'reporting', 'cardGrid', 'surface', '{"emphasis":true,"eyebrow":"Clear Reporting","heading":"Every Month You Get a Straight Answer","body":"Local SEO involves a lot of small moving parts. Reporting is how those parts stay visible to you instead of disappearing into a dashboard.","columns":4,"cards":[{"title":"What Was Completed","body":"The specific work delivered this month across profile, content, listings, and reviews."},{"title":"Why It Matters","body":"How each piece supports local visibility, relevance, or trust."},{"title":"What Changed","body":"Movement in local visibility, tracked keywords, and grid coverage across your service area."},{"title":"What Comes Next","body":"The priorities queued for next month and the reasoning behind them."}],"cta":{"label":"See How JMC Reports SEO Progress","href":"/contact"}}'::jsonb, 6 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'white', '{"eyebrow":"Questions","heading":"Local SEO Questions We Hear Often","items":[{"question":"How long does local SEO take to show results?","answer":"Most businesses start seeing measurable movement in local visibility within three to six months, though profile and listing improvements can show up sooner. The timeline depends on your market''s competitiveness, your site''s current condition, and how consistently the work is applied. We track movement monthly so you can see progress before it turns into leads."},{"question":"Why does my Google Business Profile matter so much?","answer":"For local searches, your Google Business Profile is often the first thing a customer sees and sometimes the only thing they interact with. Categories, services, posts, photos, and reviews all influence whether you appear in map results and whether someone chooses you once you do."},{"question":"Do you work with competing businesses in the same area?","answer":"No. We do not take on two clients competing for the same service in the same primary market. If your market is already covered, we will tell you upfront rather than split our attention."},{"question":"What does monthly reporting actually include?","answer":"A Monthly Recap covering the work completed, why it mattered, what moved in your tracked keywords and local grid, and the priorities for the following month. It is delivered as a plain-English summary by Loom or video call, not just a raw dashboard export."},{"question":"Do I need new pages on my website?","answer":"Often yes. Strategic SEO pages give search engines and buyers a clear answer for each service you offer. Your package includes a set number of these pages per month, and we prioritize them based on what your market is actually searching for."},{"question":"Can you do local SEO on my existing website?","answer":"In most cases, yes. We start with an audit to confirm the site can support the work. If something structural is holding visibility back, we will flag it as a priority finding rather than working around it quietly."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 7 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Find Out Where Your Local Visibility Stands","body":"A Visibility Review shows where you currently appear, where the gaps are, and which local SEO priorities are worth acting on first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Local SEO Packages","href":"/seo-packages#local"}}'::jsonb, 8 from public.pages where slug = '/local-seo-services';

-- Traditional SEO Services
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Traditional SEO Services","heading":"Organic Search Strategy for Larger and More Competitive Markets","body":"When your buyers are spread across regions, service lines, or a specialized industry, local tactics stop being enough. Traditional SEO builds visibility through search strategy, content structure, technical health, and competitor awareness, reported clearly every month.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Traditional SEO Packages","href":"/seo-packages#traditional"},"showcase":[{"kind":"stat","label":"Regional tier","title":"Campaign Scope","stats":[{"value":"60","label":"Tracked keywords"},{"value":"5","label":"Tracked competitors"},{"value":"2","label":"Strategic pages a month"}],"footnote":"Up to 90 keywords on National+"},{"kind":"roadmap","label":"The plan","title":"Strategy Roadmap","items":["Keyword and intent mapping","Strategic SEO pages","Authority-building signals"]},{"kind":"report","label":"Every month","title":"Monthly Recap","items":["Pages published","Technical issues resolved","Competitor movement","Next-step priorities"]}]}'::jsonb, 0 from public.pages where slug = '/traditional-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'audience-fit', 'cardGrid', 'white', '{"variant":"compact","eyebrow":"Is This You","heading":"Traditional SEO Fits Businesses Competing Beyond One Map Result","body":"These are the situations where a broader organic strategy does more than local optimization alone.","columns":3,"cards":[{"title":"A Regional Search Footprint","icon":"map-pin","body":"You serve several markets or a defined region rather than a single city."},{"title":"National Search Visibility","icon":"network","body":"Your buyers can be anywhere, and proximity is not what decides whether you get the work."},{"title":"Complex Services","icon":"layers","body":"What you sell takes explaining, and one services page cannot carry it."},{"title":"Longer Buyer Journeys","icon":"calendar","body":"Your deals involve research, comparison, and multiple people before anyone reaches out."},{"title":"Competitive Industries","icon":"trending-up","body":"Established competitors already rank, and gaining ground takes a plan rather than a checklist."},{"title":"Strategic Reporting","icon":"bar-chart","body":"Someone above you needs to understand where the investment is going and what it is producing."}],"cta":{"label":"Explore Traditional SEO Strategy","href":"#includes"}}'::jsonb, 1 from public.pages where slug = '/traditional-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'includes', 'cardGrid', 'surface', '{"variant":"numbered","eyebrow":"What''s Included","heading":"The Work Behind a Larger Search Footprint","body":"Traditional SEO is built on strategy and structure. These are the workstreams JMC runs each month.","columns":3,"cards":[{"title":"SEO Strategy and Roadmap","icon":"target","body":"Keyword priorities, search intent mapping, and a sequenced plan tied to business goals rather than a task list."},{"title":"Strategic SEO Pages","icon":"file-text","body":"Purpose-built pages for the services, markets, and topics your buyers are actually searching for."},{"title":"Technical SEO Monitoring","icon":"wrench","body":"Ongoing review of crawling, indexing, metadata, schema, sitemaps, and the issues that quietly cap visibility."},{"title":"Competitor and Market Visibility","icon":"search","body":"Tracking who is winning the searches you want and where the realistic openings are."},{"title":"Authority-Building Recommendations","icon":"link","body":"Practical guidance on the signals that build credibility in your space, grounded in what your market rewards."},{"title":"Monthly Recaps and Reporting","icon":"clipboard-check","body":"Dashboard reporting plus a plain-English recap that explains progress, priorities, and next steps."}],"cta":{"label":"Compare Traditional SEO Packages","href":"/seo-packages#traditional"}}'::jsonb, 2 from public.pages where slug = '/traditional-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'industries', 'cardGrid', 'white', '{"variant":"compact","eyebrow":"Industry Focus","heading":"Search Strategy Built Around How Your Industry Buys","body":"Technical services, long sales cycles, and specialized terminology all change what SEO has to do. These are the industries JMC builds traditional SEO strategy for.","columns":4,"cards":[{"title":"Oil, Gas, and Industrial","icon":"factory"},{"title":"Commercial Construction","icon":"hard-hat"},{"title":"Aerospace","icon":"compass"},{"title":"Healthcare and Life Sciences","icon":"heart-pulse"},{"title":"Maritime","icon":"network"},{"title":"Hospitality","icon":"utensils"},{"title":"Tourism","icon":"map-pin"},{"title":"Multi-Location Brands","icon":"building"}],"cta":{"label":"Talk Through Your SEO Growth Goals","href":"/contact"}}'::jsonb, 3 from public.pages where slug = '/traditional-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'footprint', 'cardGrid', 'surface', '{"eyebrow":"Campaign Scale","heading":"Match the Strategy to the Ground You Need to Cover","body":"Search footprint drives everything: how many keywords are in play, how much content the plan needs, and how many competitors are worth watching.","columns":3,"cards":[{"title":"Regional SEO","icon":"map-pin","body":"For businesses targeting a defined set of markets or a regional service footprint where each market needs its own attention."},{"title":"National SEO","icon":"network","body":"For businesses competing across broad markets and multiple service lines where visibility is not tied to geography."},{"title":"Industry-Focused SEO","icon":"layers","body":"For specialized companies whose buyers use technical language and compare a small set of credible options."}],"cta":{"label":"View Traditional SEO Packages","href":"/seo-packages#traditional"}}'::jsonb, 4 from public.pages where slug = '/traditional-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'foundation', 'featureSplit', 'white', '{"align":"right","eyebrow":"The Foundation","heading":"Content and Technical Work Have to Move Together","body":"Strong content on a site search engines struggle to crawl does not rank. A technically clean site with nothing to say does not convert. Traditional SEO keeps both moving, with competitor context to show whether the plan is working and reporting that makes it legible.","cta":{"label":"Start with a Visibility Review","href":"/contact"},"groups":[{"title":"Content Structure","icon":"file-text","body":"Pages organized around real search intent and how your services actually relate to each other."},{"title":"Technical Visibility","icon":"wrench","body":"Crawling, indexing, schema, and performance issues found and flagged before they cost you visibility."},{"title":"Competitor Tracking","icon":"search","body":"Who ranks for what, and where there is realistic room to take ground."},{"title":"Reporting Clarity","icon":"bar-chart","body":"Monthly reporting that connects the work to movement and to what happens next."}]}'::jsonb, 5 from public.pages where slug = '/traditional-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'packages', 'pricingCards', 'surface', '{"eyebrow":"Traditional SEO Packages","heading":"Structured Growth. Compounding Visibility. Built to Scale.","body":"Three levels of monthly traditional SEO, sized by how much search territory the campaign has to cover.","packageIds":["traditional-regional","traditional-national","traditional-national-plus"],"cta":{"label":"View All SEO Packages","href":"/seo-packages"}}'::jsonb, 6 from public.pages where slug = '/traditional-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'reporting', 'cardGrid', 'white', '{"emphasis":true,"eyebrow":"Clear Reporting","heading":"Complex Campaigns Need Clearer Reporting, Not Longer Reports","body":"The bigger the campaign, the easier it is for the work to become invisible. Reporting is how it stays accountable.","columns":4,"cards":[{"title":"Priority Work Completed","body":"What was delivered this month and which roadmap priority it belonged to."},{"title":"Visibility Movement","body":"Where tracked keywords and competitor positions moved, and what that means."},{"title":"Content and Technical Progress","body":"Pages published or improved, and technical issues resolved or flagged."},{"title":"Next-Step Recommendations","body":"The priorities queued next and the reasoning behind the sequence."}],"cta":{"label":"See How JMC Reports SEO Progress","href":"/contact"}}'::jsonb, 7 from public.pages where slug = '/traditional-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Traditional SEO Questions We Hear Often","items":[{"question":"What is the difference between local SEO and traditional SEO?","answer":"Local SEO focuses on visibility in a specific service area, where Google Business Profile, map results, and proximity carry a lot of weight. Traditional SEO focuses on organic visibility across broader markets, where content depth, site structure, technical health, and authority matter more than location. Some businesses need both."},{"question":"How do regional and national SEO differ in practice?","answer":"Regional campaigns concentrate on a defined set of markets, so content and tracking are organized market by market. National campaigns compete across a much larger keyword set with more established competitors, which means more content, more competitor tracking, and a longer runway before movement compounds."},{"question":"How much content will this involve?","answer":"Each package includes a set number of Strategic SEO Pages per month, from two to four depending on tier. We prioritize them against the roadmap rather than publishing on volume alone, and every page is built for a specific search intent."},{"question":"Is technical SEO included or billed separately?","answer":"Technical SEO monitoring and issue flagging are included in every traditional package. We identify problems, explain their impact, and recommend fixes. Large development work on your site is scoped separately if it falls outside the monthly plan."},{"question":"Do you guarantee rankings?","answer":"No, and you should be cautious of anyone who does. Search results are influenced by competitors, algorithm changes, and factors outside any agency''s control. What we commit to is a documented roadmap, consistent execution against it, and honest reporting on what moved."},{"question":"How does communication work during a campaign?","answer":"You get a Monthly Recap explaining the work, the movement, and the next priorities, plus a Quarterly Project Update that steps back to look at direction. Between those, we flag anything urgent rather than saving it for the next report."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 8 from public.pages where slug = '/traditional-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"See Where Your Organic Visibility Is Losing Ground","body":"A Visibility Review identifies the gaps between where you rank today and where your market is actually searching, plus the priorities worth acting on first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Traditional SEO Packages","href":"/seo-packages#traditional"}}'::jsonb, 9 from public.pages where slug = '/traditional-seo-services';

-- Real Estate SEO
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Real Estate SEO","heading":"Be the Agent Your Market Finds First","body":"Real estate search is local, personal, and competitive. JMC builds SEO strategy around the neighborhoods you work, the buyers and sellers you want, and the content that makes you a credible choice before anyone picks up the phone.","primaryCta":{"label":"Request a Real Estate Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Real Estate SEO Options","href":"#options"},"showcase":[{"kind":"channels","label":"Who is searching","title":"Both Sides of the Move","items":["Buyers researching a neighborhood","Sellers checking their market","Referrals looking you up by name"],"footnote":"Different intent, different pages"},{"kind":"coverage","label":"Your markets","title":"Neighborhood Reach","items":["Buyer intent","Seller intent","Market pages"]},{"kind":"report","label":"Every month","title":"Monthly Recap","items":["Market content published","Profile and review activity","Visibility movement","Next-step priorities"]}]}'::jsonb, 0 from public.pages where slug = '/real-estate-seo';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'audience-path', 'cardGrid', 'white', '{"eyebrow":"Where You Fit","heading":"SEO Works Differently for Agents, Teams, and Brokerages","body":"The right strategy depends on whether you are building a personal reputation, scaling one across several agents, or establishing a firm as the authority in a market.","columns":3,"cards":[{"title":"Individual Agents","icon":"users","body":"You are the brand. Visibility has to attach to your name and the neighborhoods you actually know.","cta":{"label":"Agent Growth SEO","href":"#options"}},{"title":"Real Estate Teams","icon":"layers","body":"Several agents, overlapping markets, one shared reputation to build and protect.","cta":{"label":"Team and Brokerage SEO","href":"#options"}},{"title":"Brokerages","icon":"building","body":"You need market-level authority that supports recruiting as much as it supports listings.","cta":{"label":"Team and Brokerage SEO","href":"#options"}}],"cta":{"label":"Find the Right Real Estate SEO Path","href":"/contact"}}'::jsonb, 1 from public.pages where slug = '/real-estate-seo';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'includes', 'cardGrid', 'surface', '{"variant":"split","eyebrow":"What''s Included","heading":"The Work Behind Real Estate Search Visibility","body":"Real estate SEO is less about chasing generic terms and more about owning the searches tied to your markets and your name.","columns":3,"cards":[{"title":"Local Visibility and Google Business Profile","icon":"star","body":"Profile optimization and local search work so you appear when someone searches an agent in your area."},{"title":"Neighborhood and Market Content","icon":"map-pin","body":"Pages built around the specific communities you serve, written for buyers and sellers researching a move."},{"title":"Website Structure and Service Pages","icon":"file-text","body":"Clear pages for buyers, sellers, and the markets you cover, organized so search engines understand your focus."},{"title":"Review and Trust Signals","icon":"message-square","body":"Review support and reputation work, because real estate decisions run on trust more than most industries."},{"title":"Search Visibility Tracking","icon":"gauge","body":"Tracking across your neighborhoods and market terms so you can see where you are gaining ground."},{"title":"Monthly Recaps and Reporting","icon":"clipboard-check","body":"A clear summary of the work, the movement, and the priorities queued next."}],"cta":{"label":"Explore Real Estate SEO Options","href":"#options"}}'::jsonb, 2 from public.pages where slug = '/real-estate-seo';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'growth-model', 'cardGrid', 'white', '{"variant":"compact","eyebrow":"Growth Model","heading":"The Strategy Changes With the Business Model","body":"Same market, same search results, very different SEO problems to solve.","columns":3,"cards":[{"title":"Agents Need Personal Visibility","icon":"users","body":"Your name, your neighborhoods, and your track record have to be findable and consistent. The goal is being recognized as the person who knows a specific area."},{"title":"Teams Need Scalable Visibility","icon":"layers","body":"Content and structure that support multiple agents without competing against each other for the same searches or splitting the team''s authority."},{"title":"Brokerages Need Market Authority","icon":"building","body":"Depth across markets, a site structure that holds up as agents come and go, and visibility that supports both listings and recruiting."}],"cta":{"label":"Request a Real Estate Visibility Review","href":"/contact"}}'::jsonb, 3 from public.pages where slug = '/real-estate-seo';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'neighborhood-authority', 'featureSplit', 'surface', '{"eyebrow":"Neighborhood Authority","heading":"Own the Searches That Come Before the Listing Search","body":"Long before someone searches for a specific address, they are searching for a neighborhood. What it is like to live there, what homes go for, what the schools and commute look like. Answering those questions well is how agents become the obvious local expert instead of one more name in the results.","cta":{"label":"Explore Real Estate SEO Options","href":"#options"},"groups":[{"title":"Neighborhood Content","icon":"map-pin","body":"Pages that genuinely answer what people ask about a community."},{"title":"Buyer and Seller Intent","icon":"target","body":"Separate paths, because the two search very differently."},{"title":"Local Search Presence","icon":"search","body":"Profile, listings, and local signals that reinforce your market."},{"title":"Trust Signals","icon":"shield-check","body":"Reviews and credibility markers that support the decision."}]}'::jsonb, 4 from public.pages where slug = '/real-estate-seo';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'options', 'pricingCards', 'white', '{"eyebrow":"Real Estate SEO Options","heading":"Two Paths Depending on How You Are Built","body":"Real estate SEO is scoped differently than standard local SEO packages. Reach out and we will size it against your markets and business model.","packageIds":["real-estate-agent","real-estate-team"],"cta":{"label":"Request a Real Estate Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/real-estate-seo';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'education', 'fullWidthText', 'surface', '{"eyebrow":"Continuing Education","heading":"SEO Education for Real Estate Professionals","body":"JMC teaches continuing education on search visibility for real estate professionals. If you would rather understand the fundamentals before hiring anyone, that is a reasonable place to start.","cta":{"label":"Ask About Upcoming Classes","href":"/contact"}}'::jsonb, 6 from public.pages where slug = '/real-estate-seo';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'reporting', 'cardGrid', 'white', '{"emphasis":true,"eyebrow":"Clear Reporting","heading":"Know Exactly What Your SEO Is Doing Each Month","body":"Real estate moves fast and marketing spend gets questioned. Reporting is how the work stays defensible.","columns":4,"cards":[{"title":"Visibility Movement","body":"Where you are gaining or losing ground across your neighborhoods and market terms."},{"title":"Content Progress","body":"The market and neighborhood content published or improved this month."},{"title":"Local Search Opportunities","body":"Openings in your markets worth pursuing next, and why they look reachable."},{"title":"Next-Step Recommendations","body":"The priorities queued for the coming month, in plain language."}],"cta":{"label":"See How JMC Reports SEO Progress","href":"/contact"}}'::jsonb, 7 from public.pages where slug = '/real-estate-seo';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Real Estate SEO Questions We Hear Often","items":[{"question":"Is SEO worth it for an individual agent?","answer":"It can be, if you work defined neighborhoods and want visibility that does not stop the moment you stop paying for ads. SEO builds slowly and compounds. If you need volume this month, paid channels will move faster, the two solve different problems."},{"question":"How is this different for teams and brokerages?","answer":"Individual agents need visibility tied to a personal brand and a handful of neighborhoods. Teams need content and site structure that support several agents without competing internally. Brokerages need market-level authority that holds up as the roster changes. The tactics overlap; the structure does not."},{"question":"Does a Google Business Profile matter for real estate?","answer":"Yes. Agents and brokerages appear in local search and map results, and profile completeness, activity, and reviews all influence whether you show up and whether someone contacts you."},{"question":"What does neighborhood visibility actually mean?","answer":"Appearing in searches tied to specific communities rather than only broad city-level terms. Those searches usually have less competition and much clearer intent, because someone researching a neighborhood is genuinely considering a move."},{"question":"How long before real estate SEO shows results?","answer":"Expect three to six months for meaningful movement in a moderately competitive market, longer where established agents and portals already dominate. Neighborhood content typically gains traction sooner than broad city terms."},{"question":"Who writes the content?","answer":"JMC plans and produces the content as part of your monthly scope. We will pull on your market knowledge where it makes the content genuinely better, but you are not being handed a writing assignment."}],"cta":{"label":"Request a Real Estate Visibility Review","href":"/contact"}}'::jsonb, 8 from public.pages where slug = '/real-estate-seo';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"See How You Show Up in the Neighborhoods You Work","body":"A Real Estate Visibility Review looks at where you currently appear across your markets, where the gaps are, and what is worth prioritizing first.","primaryCta":{"label":"Request a Real Estate Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Real Estate SEO Options","href":"#options"}}'::jsonb, 9 from public.pages where slug = '/real-estate-seo';

-- Monthly SEO Packages
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroCentered', NULL, '{"eyebrow":"SEO Packages","heading":"Clear SEO Packages With Clear Scope","body":"Every package includes strategy, execution, tracking, and a Monthly Recap that explains the work. Pick the lane that matches your market, and we will confirm the fit on a Visibility Review before anything starts.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Compare Packages","href":"#local"}}'::jsonb, 0 from public.pages where slug = '/seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'path-selector', 'cardGrid', 'white', '{"eyebrow":"Start Here","heading":"Three Lanes. Pick the One That Matches Your Market.","body":"The right package depends less on budget than on where your buyers are searching.","columns":3,"cards":[{"title":"Local SEO Packages","icon":"map-pin","body":"For businesses that need visibility in a defined city or service area, across search, maps, reviews, and local content.","cta":{"label":"View Local SEO Packages","href":"#local"}},{"title":"Traditional SEO Packages","icon":"trending-up","body":"For businesses competing across regions, national markets, or specialized industries with larger keyword sets.","cta":{"label":"View Traditional SEO Packages","href":"#traditional"}},{"title":"Real Estate SEO Options","icon":"home","body":"For agents, teams, and brokerages that need neighborhood visibility and content built for buyers and sellers.","cta":{"label":"View Real Estate SEO Options","href":"#real-estate"}}]}'::jsonb, 1 from public.pages where slug = '/seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'local', 'pricingCards', 'surface', '{"eyebrow":"Local SEO","heading":"Monthly Local SEO Packages","body":"Built for businesses that want to be found in their service area and turn local searches into consistent leads. Every tier includes SEO strategy and roadmap, content and on-page optimization, technical monitoring, review management, detailed reporting, and a Monthly Project Recap.","packageIds":["local-neighborhood","local-citywide","local-metro"]}'::jsonb, 2 from public.pages where slug = '/seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'traditional', 'pricingCards', 'white', '{"eyebrow":"Traditional SEO","heading":"Monthly Traditional SEO Packages","body":"Designed for businesses targeting multiple markets, service lines, or competitive search landscapes. Every tier includes SEO strategy and roadmap, Strategic SEO Pages, technical monitoring, authority-building recommendations, and reporting with a Monthly Recap.","packageIds":["traditional-regional","traditional-national","traditional-national-plus"]}'::jsonb, 3 from public.pages where slug = '/seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'real-estate', 'pricingCards', 'surface', '{"eyebrow":"Real Estate SEO","heading":"Real Estate SEO Options","body":"Real estate SEO is scoped around your markets and business model rather than a fixed tier. Reach out and we will size it on a Real Estate Visibility Review.","packageIds":["real-estate-agent","real-estate-team"],"cta":{"label":"Explore Real Estate SEO","href":"/real-estate-seo"}}'::jsonb, 4 from public.pages where slug = '/seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'onboarding', 'cardGrid', 'white', '{"variant":"numbered","eyebrow":"Onboarding","heading":"What the One-Time Onboarding Fee Covers","body":"Onboarding is the setup work that makes month one productive instead of exploratory. It happens once, at the start.","columns":3,"cards":[{"title":"Access and Setup","icon":"shield-check","body":"Getting the right access in place across your site, analytics, and profiles so nothing stalls later."},{"title":"SEO Audit","icon":"search","body":"A review of your current visibility, technical health, and the issues worth fixing first."},{"title":"Keyword and Competitor Research","icon":"target","body":"Identifying what your market actually searches for and who is currently winning those searches."},{"title":"Tracking Setup","icon":"gauge","body":"Rank tracking, local grid tracking where applicable, and the reporting connections behind them."},{"title":"Roadmap Planning","icon":"compass","body":"Turning the audit and research into a sequenced plan tied to your business goals."},{"title":"Baseline Reporting","icon":"bar-chart","body":"A starting-point snapshot, so every month afterward has something honest to measure against."}],"cta":{"label":"Start with a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-service', 'cardGrid', 'surface', '{"variant":"compact","eyebrow":"Monthly Service","heading":"What Happens Every Month After That","body":"Monthly SEO is recurring execution against the roadmap, not a repeating checklist.","columns":3,"cards":[{"title":"Roadmap Execution","icon":"list-checks","body":"Working through the prioritized plan rather than reacting to whatever surfaced that week."},{"title":"Content and Page Improvements","icon":"file-text","body":"Strategic SEO pages and improvements to existing pages, scoped to your tier."},{"title":"Local or Traditional Visibility Work","icon":"map-pin","body":"Profile, citation, and review work for local campaigns; content and authority work for traditional."},{"title":"Technical Monitoring","icon":"wrench","body":"Ongoing checks for the technical issues that quietly limit visibility."},{"title":"Tracking and Movement Review","icon":"gauge","body":"Watching what moved, what did not, and adjusting priorities accordingly."},{"title":"Monthly Recaps","icon":"clipboard-check","body":"The summary that keeps all of it visible and accountable to you."}],"cta":{"label":"Talk Through the Right Package","href":"/contact"}}'::jsonb, 6 from public.pages where slug = '/seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'reporting', 'cardGrid', 'white', '{"emphasis":true,"eyebrow":"Clear Reporting","heading":"Reporting Is Part of the Package, Not an Upsell","body":"Every package at every tier includes the same reporting commitment. This is the part most agencies treat as optional.","columns":4,"cards":[{"title":"What Was Completed","body":"The specific work delivered, in language you do not need a background in SEO to follow."},{"title":"Why It Matters","body":"How each piece supports visibility, relevance, or trust."},{"title":"What Changed","body":"Movement across tracked keywords, local grid coverage, and competitor positions."},{"title":"What Comes Next","body":"The priorities queued next and the reasoning behind them."}]}'::jsonb, 7 from public.pages where slug = '/seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'sprint-crosslink', 'calloutBanner', 'surface', '{"heading":"Not Ready for Monthly SEO Yet?","body":"A Launch Sprint is a fixed-scope, one-time engagement that puts the SEO foundation in place over 30 days and hands you a roadmap. If you start monthly service within 30 days of finishing a sprint, the onboarding fee for the matching package is waived.","primaryCta":{"label":"View Launch Sprints","href":"/launch-sprints"},"secondaryCta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 8 from public.pages where slug = '/seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'white', '{"eyebrow":"Questions","heading":"Package Questions We Hear Often","items":[{"question":"Which SEO package is right for me?","answer":"It comes down to where your buyers search. If they are nearby and proximity matters, start with Local SEO. If they are spread across regions or industries, Traditional SEO fits better. If you are in real estate, that has its own lane. We confirm the fit on a Visibility Review before anything starts."},{"question":"What is included in the onboarding fee?","answer":"Access and setup, an SEO audit, keyword and competitor research, tracking setup, roadmap planning, and baseline reporting. It is one-time, and it is what makes the first month productive rather than exploratory."},{"question":"Do I need a 12-month term?","answer":"No. SEO does compound over time and short engagements rarely show what the work is capable of, but we do not lock clients into a year to prove that."},{"question":"Can I start with a Launch Sprint instead?","answer":"Yes, and it is often the better move if your foundation needs work. If you move into monthly service within 30 days of completing a sprint, the onboarding fee for the matching package is waived."},{"question":"Can I change packages later?","answer":"Yes. Businesses commonly start at one tier and move up as their market or service area expands. We will flag it when your current tier is limiting the plan."},{"question":"What is included in the Monthly Recap?","answer":"A plain-English summary of what was completed, why it mattered, what changed, and what comes next, delivered by Loom or video call so you can ask questions rather than interpreting a PDF."},{"question":"Do all packages include reporting?","answer":"Yes. Every tier includes detailed monthly reporting and a Monthly Recap. Core packages also include a Quarterly Project Update that steps back to review direction."},{"question":"How do I know if I need Local, Traditional, or Real Estate SEO?","answer":"The short version: Local if customers come to you or you go to them within a service area. Traditional if location is not the deciding factor. Real Estate if you are an agent, team, or brokerage. If you are between two of these, that is exactly what the Visibility Review sorts out."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 9 from public.pages where slug = '/seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Not Sure Which Package Fits? Start With a Visibility Review.","body":"We will look at your market, your current visibility, and your goals, then recommend the package that actually fits, including telling you if the answer is a sprint instead.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Launch Sprints","href":"/launch-sprints"}}'::jsonb, 10 from public.pages where slug = '/seo-packages';

-- Launch Sprints
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Launch Sprints","heading":"A Fixed-Scope SEO Foundation in 30 Days","body":"A Launch Sprint is a one-time engagement that audits your current SEO, completes the core setup and optimization work, and hands you a prioritized 30-day roadmap. Fixed price, fixed scope, clear ending.","primaryCta":{"label":"Request a Sprint Consultation","href":"/contact"},"secondaryCta":{"label":"Compare Launch Sprints","href":"#options"},"showcase":[{"kind":"roadmap","label":"30 days","title":"Sprint Timeline","items":["Audit","Implementation","Handoff"],"footnote":"One fixed window, then it ends"},{"kind":"stat","label":"Fixed scope","title":"By the Numbers","stats":[{"value":"30","label":"Day sprint window"},{"value":"3","label":"Phases, start to handoff"},{"value":"5–15","label":"Priority pages optimized"}],"footnote":"Page count depends on the sprint tier"},{"kind":"report","label":"What you receive","title":"Sprint Handoff","items":["Priority findings","Completed sprint work","30-day action roadmap","Next-step direction"]}]}'::jsonb, 0 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'what-is-it', 'cardGrid', 'white', '{"eyebrow":"The Model","heading":"What a Launch Sprint Actually Is","body":"A sprint gets the foundation right before anyone commits to a monthly campaign. It is a good starting point when the groundwork has never been done properly.","columns":3,"cards":[{"title":"Fixed Scope","icon":"list-checks","body":"You know exactly what is included before it starts. The deliverables are listed on the card, not discovered along the way."},{"title":"One-Time Investment","icon":"target","body":"A single price with no recurring commitment. If monthly SEO is not the right next step, the sprint still stands on its own."},{"title":"Clear Handoff","icon":"compass","body":"You finish with the completed work and a prioritized roadmap you can act on yourself or hand to someone else."}],"cta":{"label":"Compare Launch Sprints","href":"#options"}}'::jsonb, 1 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'options', 'pricingCards', 'surface', '{"eyebrow":"Sprint Options","heading":"Three Sprints, Sized to Your Search Footprint","body":"Each sprint runs 30 days. The difference is how much ground the audit and optimization work has to cover.","packageIds":["sprint-neighborhood","sprint-regional","sprint-national"],"cta":{"label":"Talk Through the Right Sprint","href":"/contact"}}'::jsonb, 2 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'process', 'processSteps', 'white', '{"eyebrow":"How It Runs","heading":"What Happens During the Sprint","body":"Three phases across 30 days, with a defined ending rather than an open-ended engagement.","steps":[{"title":"Audit","body":"We review the current foundation, identify priority issues, and confirm what needs to be fixed first."},{"title":"Implementation","body":"We complete the included setup and optimization work inside the sprint scope."},{"title":"Handoff","body":"You receive a clear roadmap with next-step recommendations and a clean path into monthly service if you want one."}],"cta":{"label":"Request a Sprint Consultation","href":"/contact"}}'::jsonb, 3 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'not', 'cardGrid', 'surface', '{"variant":"compact","eyebrow":"Setting Expectations","heading":"What a Sprint Is Not","body":"Worth being direct about this upfront, so a sprint is chosen for the right reasons.","columns":4,"cards":[{"title":"Not a Full Monthly Campaign","body":"A sprint builds the foundation. Compounding visibility comes from sustained work after it."},{"title":"Not a Ranking Guarantee","body":"No one can promise positions. A sprint removes obstacles and sets direction."},{"title":"Not a Replacement for Content","body":"Long-term visibility needs ongoing content. A sprint optimizes what already exists."},{"title":"Not Ongoing Tracking","body":"You get a baseline snapshot. Continuous tracking and reporting come with monthly service."}],"cta":{"label":"See Monthly SEO Packages","href":"/seo-packages"}}'::jsonb, 4 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'transition', 'calloutBanner', 'white', '{"heading":"Sprint First, Then Monthly, With the Onboarding Fee Waived","body":"If you begin monthly service within 30 calendar days of completing your sprint, the one-time onboarding fee for the matching monthly package is waived. The sprint work carries directly into the monthly roadmap rather than being repeated.","primaryCta":{"label":"View Monthly SEO Packages","href":"/seo-packages"},"secondaryCta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'handoff', 'cardGrid', 'surface', '{"emphasis":true,"eyebrow":"The Handoff","heading":"What You Walk Away With","body":"The handoff is the point of the sprint. It should feel organized, not like a loose audit document dropped in your inbox.","columns":4,"cards":[{"title":"Priority Findings","body":"The issues holding visibility back, ranked by impact rather than listed alphabetically."},{"title":"Completed Sprint Work","body":"A clear record of everything delivered inside the sprint scope."},{"title":"Roadmap Recommendations","body":"A prioritized 30-day action roadmap covering what should happen next."},{"title":"Next-Step Direction","body":"An honest read on whether monthly SEO makes sense for you, and at what level."}],"cta":{"label":"Talk Through Your SEO Starting Point","href":"/contact"}}'::jsonb, 6 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'white', '{"eyebrow":"Questions","heading":"Launch Sprint Questions We Hear Often","items":[{"question":"Who is a Launch Sprint best for?","answer":"Businesses whose SEO foundation has never been properly set up, or who want to see how JMC works before committing to a monthly engagement. If you already have solid technical footing and consistent content, monthly service is usually the better starting point."},{"question":"How long does a sprint take?","answer":"Thirty days from kickoff. That window is fixed, which is what keeps the scope honest on both sides."},{"question":"What happens after the sprint?","answer":"You receive the completed work and a prioritized 30-day roadmap. From there you can move into monthly SEO with us, hand the roadmap to another team, or execute it yourself. All three are legitimate outcomes."},{"question":"Do I have to move into monthly SEO afterward?","answer":"No. There is no obligation and no automatic rollover. The waived onboarding fee is an incentive if you do continue, not a commitment you make upfront."},{"question":"Is a sprint enough to rank?","answer":"Usually not on its own. A sprint clears obstacles, fixes the foundation, and sets direction. Rankings in competitive markets come from sustained content and optimization over months. Anyone telling you a one-time engagement will get you ranking is overselling it."},{"question":"Which sprint should I choose?","answer":"It depends on your search footprint. Neighborhood suits a single local market and includes Google Business Profile and citation work. Regional suits multiple markets. National suits broad competitive visibility. We will confirm the fit on a consultation before you commit."},{"question":"What is included in the handoff?","answer":"Priority findings, documentation of the completed sprint work, a 30-day action roadmap, and a direct recommendation on next steps."},{"question":"Can the sprint cost be applied toward monthly service?","answer":"The sprint fee itself is separate, but starting monthly service within 30 days of completing it waives the onboarding fee for the matching package, between $349 and $1,295 depending on the tier."}],"cta":{"label":"Request a Sprint Consultation","href":"/contact"}}'::jsonb, 7 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Solid Foundation Instead of Guessing","body":"A sprint consultation confirms which sprint fits your market, what the audit is likely to surface, and whether a sprint is the right starting point at all.","primaryCta":{"label":"Request a Sprint Consultation","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/seo-packages"}}'::jsonb, 8 from public.pages where slug = '/launch-sprints';

-- About JMC
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroCentered', NULL, '{"eyebrow":"About JMC","heading":"Practical SEO, Explained in Plain English","body":"Jordan Marketing Consultants is a Houston-area SEO agency rooted in League City, helping local, regional, and industry-focused businesses improve search visibility through practical SEO strategy, content planning, local optimization, and clear reporting.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View SEO Packages","href":"/seo-packages"}}'::jsonb, 0 from public.pages where slug = '/about';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'approach', 'cardGrid', 'white', '{"variant":"split","eyebrow":"How We Work","heading":"SEO Should Be Understandable Before It Is Impressive","body":"Most businesses that have hired an SEO agency before describe the same experience: work happened, invoices arrived, and nobody could explain what changed. JMC is built around fixing that.","columns":3,"cards":[{"title":"Scope Before Work","icon":"list-checks","body":"You know what is included before anything starts. No discovering the boundaries of your package three months in."},{"title":"Roadmap Over Tasks","icon":"compass","body":"Work is sequenced against a documented plan tied to your goals, not pulled from a generic monthly checklist."},{"title":"Reporting You Read","icon":"bar-chart","body":"A Monthly Recap in plain language, delivered by Loom or a call, so you can ask questions instead of decoding a dashboard."}]}'::jsonb, 1 from public.pages where slug = '/about';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'houston', 'fullWidthText', 'surface', '{"eyebrow":"Houston-Area SEO Agency","heading":"Rooted in League City. Built for Houston-Area Growth.","body":"JMC is based in League City and works with businesses across the Greater Houston area and beyond. Being local matters for understanding a market, but it is not a boundary. Traditional SEO clients compete regionally and nationally, and the work is built around where your customers actually are.","cta":{"label":"Explore SEO Services","href":"/local-seo-services"}}'::jsonb, 2 from public.pages where slug = '/about';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'specialties', 'cardGrid', 'white', '{"eyebrow":"What We Focus On","heading":"Three Service Lanes, One Standard","body":"Different markets need different strategies. The commitment to clear scope, documented priorities, and honest reporting does not change between them.","columns":3,"cards":[{"title":"Local SEO","icon":"map-pin","body":"For businesses that need visibility in a defined city or service area.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"trending-up","body":"For businesses competing across regions, national markets, or specialized industries.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}},{"title":"Real Estate SEO","icon":"home","body":"For agents, teams, and brokerages building neighborhood-level visibility.","cta":{"label":"Explore Real Estate SEO","href":"/real-estate-seo"}}]}'::jsonb, 3 from public.pages where slug = '/about';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'process', 'processSteps', 'surface', '{"eyebrow":"The Process","heading":"A Clear SEO Process From Review to Recap","body":"The same four steps run every engagement, whether it is a local campaign or a national one.","steps":[{"title":"Visibility Review","body":"We review where your business currently shows up, where visibility is weak, and which opportunities are worth prioritizing."},{"title":"SEO Roadmap","body":"We organize the work around keyword priorities, content needs, local visibility, technical issues, and business goals."},{"title":"Implementation","body":"We complete the scoped SEO work, content updates, local optimization, and technical improvements tied to the plan."},{"title":"Monthly Recap","body":"You receive a clear summary of what was completed, what changed, and what should happen next."}],"cta":{"label":"Start with a Visibility Review","href":"/contact"}}'::jsonb, 4 from public.pages where slug = '/about';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Let''s Look at Where Your Visibility Stands","body":"A Visibility Review is the starting point for every JMC engagement, and it is useful even if you decide not to work with us.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View SEO Packages","href":"/seo-packages"}}'::jsonb, 5 from public.pages where slug = '/about';

-- Resources
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroCentered', NULL, '{"eyebrow":"Resources","heading":"SEO, Explained Without the Jargon","body":"Straight answers to the questions business owners actually ask about search visibility. We are building this out as we go. If something you need is missing, ask us directly.","primaryCta":{"label":"Ask an SEO Question","href":"/contact"},"secondaryCta":{"label":"View SEO Packages","href":"/seo-packages"}}'::jsonb, 0 from public.pages where slug = '/resources';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'topics', 'cardGrid', 'white', '{"variant":"compact","eyebrow":"Topics","heading":"What We Write About","body":"The areas where clear information saves businesses the most money.","columns":3,"cards":[{"title":"Local Search","icon":"map-pin","body":"How Google Business Profile, reviews, citations, and local content actually influence whether you show up nearby."},{"title":"Organic Search Strategy","icon":"trending-up","body":"How keyword strategy, content structure, and technical health work together across larger markets."},{"title":"SEO Reporting","icon":"bar-chart","body":"What to expect from an agency report, and the questions worth asking when something looks vague."},{"title":"Real Estate SEO","icon":"home","body":"How agents, teams, and brokerages build neighborhood visibility that compounds over time."},{"title":"Technical SEO","icon":"wrench","body":"The structural issues that quietly cap visibility, and how to tell whether yours are serious."},{"title":"AI and Answer Engines","icon":"search","body":"How search behavior is shifting, and which SEO fundamentals matter more because of it."}]}'::jsonb, 1 from public.pages where slug = '/resources';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'ai-search', 'featureSplit', 'surface', '{"eyebrow":"Search Is Changing","heading":"SEO Built for How People Search Now","body":"People search across Google, maps, organic results, and increasingly AI-powered answer tools. Nobody can guarantee placement inside an AI answer, and you should be skeptical of anyone who says otherwise. What does help is the same practical work that has always helped: clear service pages, strong site structure, sound internal linking, accurate schema, and content that establishes what you do and where you do it.","cta":{"label":"Talk Through Your SEO Strategy","href":"/contact"},"groups":[{"title":"Clear Service Pages","icon":"file-text","body":"Unambiguous answers about what you offer and to whom."},{"title":"Site Structure","icon":"network","body":"Organization that makes relationships between services obvious."},{"title":"Schema and Entities","icon":"layers","body":"Structured data that states who you are and where you work."},{"title":"Topical Authority","icon":"shield-check","body":"Depth in your actual subject area rather than thin coverage everywhere."}]}'::jsonb, 2 from public.pages where slug = '/resources';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'articles', 'postList', 'surface', '{"eyebrow":"Articles","heading":"Latest From the Resources Hub","body":"Plain-English explainers, written as the questions come up.","limit":6,"emptyMessage":"The first articles are being written now. In the meantime, ask us the question directly. We answer it either way.","cta":{"label":"Ask an SEO Question","href":"/contact"}}'::jsonb, 3 from public.pages where slug = '/resources';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Have a Question We Haven''t Written About Yet?","body":"Ask it directly. If it is useful to you, it is probably useful to other businesses in the same position, and it may well become the next resource here.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View SEO Packages","href":"/seo-packages"}}'::jsonb, 4 from public.pages where slug = '/resources';

-- Link Hub
insert into public.sections (page_id, key, type, tone, data, position) select id, 'links', 'linkStack', NULL, '{"eyebrow":"@htxseo","theme":"dark","heading":"Houston’s SEO Agency","body":"Houston-area SEO. Practical strategy, local optimization, content planning, and reporting you can actually read.","socials":[{"platform":"instagram","href":"https://instagram.com/"},{"platform":"facebook","href":"https://facebook.com/"},{"platform":"linkedin","href":"https://linkedin.com/"}],"links":[{"label":"Request a Visibility Review","href":"/contact","description":"Where you show up now, and what to fix first","icon":"target","featured":true},{"label":"SEO Packages & Pricing","href":"/seo-packages","description":"Local, traditional, and launch sprints","icon":"layers"},{"label":"Local SEO Services","href":"/local-seo-services","description":"Google Business Profile, citations, local content","icon":"map-pin"},{"label":"SEO Resources","href":"/resources","description":"Plain-English explainers, no jargon","icon":"file-text"},{"label":"Call (281) 989-0468","href":"tel:+12819890468","icon":"message-square"}],"footnote":"League City, TX · Serving the Greater Houston area"}'::jsonb, 0 from public.pages where slug = '/links';

